# shellcheck disable=SC2034

vx_build() {
  cmd=()
  vx_scan=false
  vx_takes_path=false
  case "$1" in
    sca)
      cmd=(sca)
      vx_scan=true
      vx_takes_path=true
      vx_flag_lines --vex "${VX_IN_VEX:-}"
      ;;
    sast)
      cmd=(sast)
      vx_scan=true
      vx_takes_path=true
      vx_flag_lines --vex "${VX_IN_VEX:-}"
