      cmd=(secrets)
      vx_scan=true
      vx_takes_path=true
      vx_flag_lines --vex "${VX_IN_VEX:-}"
      ;;
    iac)
      cmd=(iac)
      vx_scan=true
      vx_takes_path=true
      vx_flag_lines --vex "${VX_IN_VEX:-}"
      ;;
    containers)
      cmd=(containers)
      vx_scan=true
      vx_takes_path=true
      vx_flag_lines --vex "${VX_IN_VEX:-}"
      ;;
    license)
      cmd=(license)
      vx_takes_path=true
      ;;
    malscan)
      cmd=(malscan)
      vx_takes_path=true
      ;;
    analyze)
      cmd=(analyze)
      vx_takes_path=true
      ;;
    cbom)
      cmd=(cbom)
      vx_takes_path=true
      ;;
    aibom)
      cmd=(aibom)
      vx_takes_path=true
      ;;
    sbom)
      cmd=(cdx)
      vx_takes_path=true
      vx_bool --sign "${VX_IN_SIGN:-}"
      ;;
    upload)
      cmd=(upload --json)
      vx_flag --file "${VX_IN_UPLOAD_FILE:-}"
      vx_flag --format "${VX_IN_UPLOAD_FORMAT:-}"
      ;;
    gha-upload)
      cmd=(gha upload --json)
      ;;
    tea-release)
      cmd=(tea release)
      vx_lines "${VX_IN_TEA_FILES:-}"
      vx_flag --product "${VX_IN_TEA_PRODUCT:-}"
      vx_flag --purl "${VX_IN_TEA_PURL:-}"
      vx_flag --version "${VX_IN_TEA_VERSION:-}"
      vx_flag --date "${VX_IN_TEA_DATE:-}"
      vx_bool --pre-release "${VX_IN_TEA_PRE_RELEASE:-}"
      vx_flag --visibility "${VX_IN_TEA_VISIBILITY:-}"
